/**
 * Returns a list of the items in the iterable that also appear in the list.
 * The list is sorted by count of appearances in the iterable, then by first appearance in the iterable.
 * Then by count of appearances in the list, then by first appearance in the list.
 * If two items have the same appearance counts, their original order is preserved.
 *
 * @param {iterable<string>} iterable – the items to deduplicate and count.
 * @param {iterable<string>} list – the items to match against.
 * @returns {iterable<string>} – the unique items, sorted by count then first appearance in the iterable, then the list.
 */
function dedupe(iterable, list) {
  // dedupe is an O(n) map from item to [count, firstAppearanceIndex].
  const dedupe = {};
  let i = 0;
  for (const item of iterable) dedupe[item] = [0, i++];
  for (let i = 0; i < iterable.length; i++) {
    const item = iterable[i];
    dedupe[item][0]++;
  }
  for (let i = 0; i < iterable.length; i++) {
    const item = iterable[i];
    if (!dedupe[item][0]) throw new Error('unexpected item reaches end of iterable without being incremented');
  }
  // groupBy is an O(n) map from count to the items with that count.
  const groupBy = {};
  for (const item in dedupe) {
    // get the deduped info for this item
    const [count, firstAppearance] = dedupe[item];
    // get the group for this count
    const group = groupBy[count]?? {};
    // put this item's index in the group; use index instead of the item itself to preserve order.
    group[firstAppearance] = item;
    groupBy[count] = group;
  }
  // reverse the count order
  const counts = Object.keys(groupBy).sort((a, b) => b - a);
  // flatten the groups into the result
  const result = [];
  for (const count of counts) {
    for (const item of Object.values(groupBy[count])) {
      result.push(item);
    }
  }
  return result;
}
